/*
 * kbd_$state_lookup - find the keyboard state-machine entry for (state, key)
 *
 * Original address: 0x00E1C9FC (module-local; the SAU2 map has no symbol
 * here, it is the first routine of "I E1C9FC KBD size = 4F0")
 * Size: 102 bytes (0x00E1C9FC .. 0x00E1CA61)
 * Generated by: Claude Opus 5.5
 *
 * A Pascal function returning a pointer in A0.  It does not load A5; both
 * callers (KBD_$RCV 0x00E1CCDA, kbd_$fetch_key 0x00E1CB44) have set
 * A5 = 0xE2DDE4, the KBD data segment: (0x18,A5) kbd_$state_range,
 * (0xc0,A5) kbd_$state_table.
 *
 * Frame (link.w A6,-0xc): (0x8,A6) state word, (0xa,A6) key byte (the high
 * half of a word slot: `move.b (A2),-(SP)` / `move.w D4w,-(SP)`).
 *
 * Blocks:
 *   0x00E1CA04-0x00E1CA1A  D1w = state << 2 (word); D2w = limit - 1 - first;
 *                          bmi (no entries) -> default
 *   0x00E1CA1C-0x00E1CA46  i = first; A0 = &table[i]; compare key; dbf D2w,
 *                          i.e. limit - first iterations; hit -> &table[i]
 *   0x00E1CA4A-0x00E1CA54  default: &table[limit]
 */

#include "kbd/kbd_internal.h"

kbd_$state_entry_t *kbd_$state_lookup(uint16_t state, uint8_t key)
{
    uint16_t d1;            /* D1w */
    int16_t count;          /* D2w */
    int16_t i;              /* D3w */

    /* 0x00E1CA0C-0x00E1CA0E: a word shift, the index is sign-extended */
    d1 = (uint16_t)(state << 2);

    /* 0x00E1CA10-0x00E1CA1A */
    count = (int16_t)(kbd_$state_range[(int16_t)d1 / 2 + 1] - 1
                      - kbd_$state_range[(int16_t)d1 / 2]);
    if (count >= 0) {
        /* 0x00E1CA1C-0x00E1CA46 */
        i = (int16_t)kbd_$state_range[(int16_t)d1 / 2];
        do {
            /* TODO(source-kz1g): states 5..14 index past the ten entries,
             * into the bytes that follow the KBD segment in the image. */
            if (kbd_$state_table[i].key == key) {
                return &kbd_$state_table[i];        /* 0x00E1CA32-0x00E1CA40 */
            }
            i++;
        } while (--count != -1);
    }

    /* 0x00E1CA4A-0x00E1CA54 */
    return &kbd_$state_table[(int16_t)kbd_$state_range[(int16_t)d1 / 2 + 1]];
}
